INSERT INTO `paper` VALUES (4, 'aminer_004', 'Attention Is All You Need', 'We propose a new simple network architecture, the Transformer, based solely on attention mechanisms, dispensing with recurrence and convolutions entirely.', '[\"Transformer\",\"Attention\",\"NLP\",\"Sequence Model\"]', '[\"Vaswani, A\",\"Shazeer, N\"]', 'NeurIPS', 2017, 50000, '[0.248915, 0.215459, -0.349347, 0.210468, -0.11321, 0.102526, -0.120012, -0.111399, 0.073413, 0.021592, 0.169978, -0.084235, -0.03247, 0.323633, 0.160068, -0.047293, -0.219993, 0.068757, -0.021863, -0.048201, -0.191786, -0.04621, -0.087928, -0.13556, 0.018604, -0.256125, -0.062929, 0.076247, 0.198435, -0.285033, -0.406289, 0.131458]', 0, '2026-03-21 22:28:30', '2026-05-29 18:07:49', '[0.0, 0.0, 4.0, 203.0, 2.0, 2.0, 128.0, 2.0, 0.0, 0.4667]');
