INSERT INTO `paper` VALUES (6, 'aminer_000000', 'Advances in Reinforcement Learning: Method and Application #0', 'In this paper, we propose a novel approach to reinforcement learning. Our method leverages RL, Q-learning, MDP to achieve state-of-the-art performance on benchmark datasets.', '[\"RL\",\"Q-learning\",\"MDP\",\"Reinforcement Learning\"]', '[\"author_000\",\"author_001\"]', 'ICLR', 2016, 4477, '[0.151945, -0.026999, 0.14422, 0.311337, -0.476409, -0.034558, 0.026175, -0.101276, -0.041226, -0.151223, 0.269344, 0.006866, -0.236204, 0.393955, 0.050093, -0.209886, -0.002155, -0.171629, 0.053719, -0.201565, 0.032467, -0.229232, 0.025374, 0.035154, -0.039807, -0.125307, 0.006397, -0.021993, 0.262523, 0.05229, 0.209279, 0.054027]', 0, '2026-04-26 22:59:28', '2026-05-29 18:07:49', '[13.0, 0.0, 4.0, 418.0, 2.0, 53.0, 130.0, 2.0, 0.0, 0.4]');
INSERT INTO `paper` VALUES (7, 'aminer_000001', 'Advances in Natural Language Processing: Method and Application #1', 'In this paper, we propose a novel approach to natural language processing. Our method leverages NLP, transformer, BERT to achieve state-of-the-art performance on benchmark datasets.', '[\"NLP\", \"transformer\", \"BERT\", \"Natural Language Processing\"]', '[\"author_003\"]', 'NeurIPS', 2018, 1915, '[0.11138, -0.093401, -0.032448, 0.144217, -0.34362, -0.144848, 0.219402, 0.015791, -0.070127, -0.314747, 0.170656, 0.016344, 0.071455, 0.322635, 0.243591, -0.158153, 0.155933, -0.183955, 0.254028, 0.038746, -0.179593, -0.035147, 0.227605, -0.088513, -0.207309, 0.047423, 0.098445, -0.109058, 0.030782, 0.125146, 0.37359, -0.048495]', 0, '2026-04-26 22:59:28', '2026-05-29 18:07:49', '[18.0, 0.0, 4.0, 423.0, 1.0, 55.0, 128.0, 0.0, 0.0, 0.5333]');
INSERT INTO `paper` VALUES (8, 'aminer_000002', 'Advances in Graph Neural Networks: Method and Application #2', 'In this paper, we propose a novel approach to graph neural networks. Our method leverages GNN, node classification, link prediction to achieve state-of-the-art performance on benchmark datasets.', '[\"GNN\", \"node classification\", \"link prediction\", \"Graph Neural Networks\"]', '[\"author_006\", \"author_007\", \"author_008\"]', 'ICLR', 2018, 2767, '[0.087146, -0.169006, 0.225248, 0.266716, -0.417345, -0.278606, -0.038399, -0.131385, 0.032961, -0.106404, 0.283226, 0.224341, -0.152126, 0.29973, -0.031457, -0.211744, 0.059222, -0.184559, 0.088725, -0.096894, 0.059374, -0.200169, 0.086277, 0.014143, -0.042683, -0.068494, 0.047075, 0.056509, 0.120972, 0.114666, 0.350457, -0.032913]', 0, '2026-04-26 22:59:28', '2026-05-29 18:07:49', '[16.0, 2.0, 4.0, 406.0, 3.0, 56.0, 130.0, 2.0, 1.0, 0.5333]');
INSERT INTO `paper` VALUES (9, 'aminer_000003', 'Advances in Knowledge Graphs: Method and Application #3', 'In this paper, we propose a novel approach to knowledge graphs. Our method leverages KG, TransE, entity embedding to achieve state-of-the-art performance on benchmark datasets.', '[\"KG\", \"TransE\", \"entity embedding\", \"Knowledge Graphs\"]', '[\"author_009\", \"author_010\", \"author_011\"]', 'KDD', 2015, 3773, '[0.094463, -0.213932, 0.266778, 0.232493, -0.457943, -0.158941, 0.015342, -0.115014, -0.010664, -0.157031, 0.31086, 0.170921, -0.116561, 0.311375, -0.037356, -0.144803, 0.107182, -0.125994, 0.087139, -0.083038, 0.049087, -0.220589, 0.08755, -0.019555, -0.124072, -0.121776, 0.0486, 0.057401, 0.111702, 0.152749, 0.338865, 0.025263]', 0, '2026-04-26 22:59:28', '2026-05-29 18:07:49', '[21.0, 1.0, 4.0, 404.0, 3.0, 58.0, 117.0, 2.0, 1.0, 0.3333]');
